function book(slug: string, title: string, path: string, menu: string, purpose: string, controls: [string, string][], operations: ManualOperation[], verify: string[], next: string[], taskRoute?: string): PharmacyPageGuide {
  return {
    slug, title, category: 'accounting', route: `/pharmacy/accounting${path}`, open: `${bookOpen} > ${menu}`,
    purpose, controls, operations, after: operations[operations.length - 1].result, verify,
    recovery: [load, retry, access, 'If a period, version, mapping, evidence or balance check blocks an action, resolve the original evidence with the authorized reviewer. Do not invent a balancing entry or repeat a completed payment.'],
    next, ...(taskRoute ? { taskRoute } : {}),
  };
}
